function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let count = 1;
  let slots = 2;
  for (let i = 1; i < root.length; i++) {
    if (slots === 0) return 'Some values have no parent in the level-order list.';
    slots--;
    if (root[i] !== null) {
      count++;
      slots += 2;
    }
  }
  if (count > 100) return 'The tree has at most 100 nodes.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < -100 || v > 100))) return 'Each value is an integer between -100 and 100.';
  return null;
}

