function findLeaves(root) {
  const removed = new Set();
  const gone = node => !node || removed.has(node);
  const rounds = [];
  while (!removed.has(root)) {
    const round = [];
    const stack = [root];
    while (stack.length) {
      const node = stack.pop();
      if (gone(node)) continue;
      if (gone(node.left) && gone(node.right)) round.push(node);
      stack.push(node.left, node.right);
    }
    for (const node of round) removed.add(node);
    rounds.push(round.map(node => node.val));
  }
  return rounds;
}

