function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 90 + pick(11) : 1 + pick(10);
  const top = size === 'large' || rand() < 0.5 ? 100 : 2;
  const shape = pick(3);
  const nodes = [{ val: pick(2 * top + 1) - top, left: null, right: null }];
  for (let i = 1; i < n; i++) {
    const node = { val: pick(2 * top + 1) - top, left: null, right: null };
    for (;;) {
      // shape 0: anywhere; shape 1: near the newest node (long paths); shape 2: fill in order (complete tree).
      const parent = shape === 0 ? nodes[pick(nodes.length)] : shape === 1 ? nodes[nodes.length - 1 - pick(Math.min(2, nodes.length))] : nodes[(i - 1) >> 1];
      const side = shape === 2 ? (i % 2 === 1 ? 'left' : 'right') : rand() < 0.5 ? 'left' : 'right';
      const other = side === 'left' ? 'right' : 'left';
      if (!parent[side]) { parent[side] = node; break; }
      if (!parent[other]) { parent[other] = node; break; }
    }
    nodes.push(node);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
